package day1.part2;

public class Program13_Multiples_of_Three {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		for(int i=1; i<=10;i++) {
			if ((3*i)%2==0) 
				System.out.println("Hello");
			else if ((3*i)%5==0)
				System.out.println("Bye");
			else {
				System.out.println(3*i);
			}

			
			
		}

	}

}
